package com.gomgomapps.math.core;
import java.util.*;import java.util.regex.*;
/** Mixed-number conversion and sums above one, checked from the displayed givens. */
public final class MixedNumberFoundations {
 private MixedNumberFoundations(){}
 public static final String TO_IMPROPER="el_mixed_to_improper",TO_MIXED="el_improper_to_mixed",SUM="fractionSumToMixed";
 public static final Catalog.Skill SKILL=new Catalog.Skill(SUM,"분수의 합을 대분수로 나타내기",5,1,1,"","mixedStatement",24,"fracAddLike,el_improper_to_mixed","같은 분모의 분자를 더하고 몫과 나머지로 대분수를 나타낸다.");
 public static boolean supports(String id){return TO_IMPROPER.equals(id)||TO_MIXED.equals(id)||SUM.equals(id);}
 // Returned values are whole/numerator/denominator for conversion, or two numerators/denominator for addition.
 public static int[] read(Question q){if(q==null||q.prompt==null||!supports(q.skillId))return null;String regex=TO_IMPROPER.equals(q.skillId)?"(\\d{1,2})와 (\\d{1,2})/(\\d{1,2})을 가분수로 나타내세요\\.\\n□/(\\d{1,2})":TO_MIXED.equals(q.skillId)?"(\\d{1,2})/(\\d{1,2})을 대분수로 나타내세요\\.\\n□와 □/(\\d{1,2})":"분수의 합을 가분수와 대분수로 나타내세요\\.\\n(\\d{1,2})/(\\d{1,2}) \\+ (\\d{1,2})/(\\d{1,2}) = □/(\\d{1,2}) = □와 □/(\\d{1,2})";Matcher m=Pattern.compile(regex).matcher(q.prompt);if(!m.matches())return null;
  int a=Integer.parseInt(m.group(1)),b=Integer.parseInt(m.group(2));if(TO_IMPROPER.equals(q.skillId)){int d=Integer.parseInt(m.group(3));return a>=1&&a<=6&&b>=1&&b<d&&d>=2&&d<=12&&d==Integer.parseInt(m.group(4))?new int[]{a,b,d}:null;}
  if(TO_MIXED.equals(q.skillId))return b>=2&&b<=12&&a>b&&a<7*b&&a%b!=0&&b==Integer.parseInt(m.group(3))?new int[]{a/b,a%b,b}:null;
  int c=Integer.parseInt(m.group(3));for(int i=4;i<=6;i++)if(b!=Integer.parseInt(m.group(i)))return null;return b>=3&&b<=12&&a>=1&&a<b&&c>=1&&c<b&&a+c>b?new int[]{a,c,b}:null;
 }
 static int[] result(String id,int[] v){return TO_IMPROPER.equals(id)?new int[]{v[0]*v[2]+v[1]}:TO_MIXED.equals(id)?new int[]{v[0],v[1]}:new int[]{v[0]+v[1],(v[0]+v[1])/v[2],(v[0]+v[1])%v[2]};}
 static Checker.Result check(Question q,List<String> answers){int[] v=read(q);if(v==null)return new Checker.Result(Checker.Status.INPUT_NEEDED,0,"문제 확인 필요");int[] expected=result(q.skillId,v);if(answers==null||answers.size()!=expected.length)return new Checker.Result(Checker.Status.INPUT_NEEDED,0,"답 입력 필요");for(int i=0;i<expected.length;i++){String raw=answers.get(i)==null?"":answers.get(i).trim();if(raw.isEmpty()||raw.length()>32)return new Checker.Result(Checker.Status.INPUT_NEEDED,i,"답 입력 필요");try{if(!Expression.number(raw).equals(Rational.of(expected[i])))return new Checker.Result(Checker.Status.WRONG_ANSWER,i,"이 답 확인");}catch(RuntimeException ex){return new Checker.Result(Checker.Status.INPUT_NEEDED,i,"답 입력 필요");}}return new Checker.Result(Checker.Status.CORRECT,-1,"계산 확인 완료");}
 static Question next(String id,Random random,CurriculumLimits limits,Map<String,Integer> recent){List<int[]> conditions=new ArrayList<>();for(int d:limits.fractionDenominators()){if(d<2||d>12)continue;if(SUM.equals(id)){for(int a=1;a<d;a++)for(int b=1;b<d;b++)if(a+b>d)conditions.add(new int[]{a,b,d});}else for(int w=1;w<=6;w++)for(int n=1;n<d;n++)conditions.add(new int[]{w,n,d});}return IndexedQuestionSupply.choose(conditions.size(),i->question(id,conditions.get(i)),random,limits,recent);}
 static Question question(String id,int[] v){int a=v[0],b=v[1],d=v[2];String prompt=TO_IMPROPER.equals(id)?a+"와 "+b+"/"+d+"을 가분수로 나타내세요.\n□/"+d:TO_MIXED.equals(id)?(a*d+b)+"/"+d+"을 대분수로 나타내세요.\n□와 □/"+d:"분수의 합을 가분수와 대분수로 나타내세요.\n"+a+"/"+d+" + "+b+"/"+d+" = □/"+d+" = □와 □/"+d;Question q=new Question(id,prompt,"",Arrays.stream(result(id,v)).mapToObj(Integer::toString).toArray(String[]::new));q.labels=TO_IMPROPER.equals(id)?new String[]{"가분수 분자"}:TO_MIXED.equals(id)?new String[]{"자연수 부분","분자"}:new String[]{"가분수 분자","자연수 부분","남은 분자"};q.stepSupport=false;attach(q);return q;}
 static void step(StudyGuide g,String instruction,String relation,int value){g.step(instruction,relation+" = ","",Integer.toString(value));}
 public static void attach(Question q){int[] v=read(q);if(v==null)return;int a=v[0],b=v[1],d=v[2];StudyGuide g=new StudyGuide().transfer(false);g.teachingVersion=SUM.equals(q.skillId)?"mixed-number-foundations-v1":"fraction-concept-relations-v1";if(TO_IMPROPER.equals(q.skillId)){step(g,"대분수의 자연수 부분을 쓰세요.","자연수 부분 w",a);step(g,"문제의 분자를 쓰세요.","분자 a",b);step(g,"문제의 분모를 쓰세요.","분모 b",d);step(g,"자연수 부분에 분모를 곱하세요.","곱 t = w × b",a*d);step(g,"앞에서 구한 곱에 분자를 더하세요.","가분수 분자 n = t + a",a*d+b);g.fractionResult(4,2);}else if(TO_MIXED.equals(q.skillId)){int n=a*d+b;step(g,"문제의 분자를 쓰세요.","분자 n",n);step(g,"문제의 분모를 쓰세요.","분모 d",d);step(g,"분자를 분모로 나누어 몫을 구하세요.","자연수 부분 w = n ÷ d의 몫",a);step(g,"분자에서 몫과 분모의 곱을 빼세요. 나머지가 새 분자입니다.","새 분자 r = n − w × d",b);g.mixedResult(2,3,1);}else{int n=a+b,w=n/d,r=n%d;step(g,"첫 번째 분자의 값을 쓰세요.","첫 분자 a",a);step(g,"두 번째 분자의 값을 쓰세요.","둘째 분자 c",b);step(g,"두 분수의 같은 분모를 쓰세요.","분모 d",d);step(g,"두 분자를 더하세요.","가분수 분자 n = a + c",n);step(g,"합의 분자를 분모로 나누어 몫을 구하세요.","자연수 부분 w = n ÷ d의 몫",w);step(g,"합의 분자에서 몫과 분모의 곱을 빼세요.","남은 분자 r = n − w × d",r);g.mixedResult(4,5,2);}q.studyGuide=g;if(!SUM.equals(q.skillId))q.diagram=FractionGivenDiagram.forQuestion(q);}
 public static String[] referenceLabels(String id){return TO_IMPROPER.equals(id)?new String[]{"자연수 부분 w","분자 a","분모 b","곱 t","가분수 분자 n"}:TO_MIXED.equals(id)?new String[]{"분자 n","분모 d","자연수 부분 w","새 분자 r"}:new String[]{"첫 분자 a","둘째 분자 c","분모 d","가분수 분자 n","자연수 부분 w","남은 분자 r"};}
 public static int[] referenceIndices(String id,int stage){if(TO_IMPROPER.equals(id))return stage==3?new int[]{0,2}:stage==4?new int[]{3,1}:new int[0];if(TO_MIXED.equals(id))return stage==2?new int[]{0,1}:stage==3?new int[]{0,1,2}:new int[0];return stage==3?new int[]{0,1}:stage==4?new int[]{3,2}:stage==5?new int[]{3,2,4}:new int[0];}

}
